select * from jsonb_populate_recordset(null::public.temples, $rtam$[{"id":"23e28b67-e5cf-4f63-8a8a-d7856944f1c4","name":"Ambika Mata Temple","deity":"Ambika (Durga)","sampradaya":"Shakta","significance":[],"country":"India","state":"Rajasthan","district":"Salumbar","town":"Jariyana","latitude":24.29117,"longitude":73.84533,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Tiri River","river_distance_km":0.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:14.599574+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A tenth-century temple at Jagat near Udaipur, set in a rock cleft, dedicated to Ambika, a form of Durga worshipped as Shakti. Built under Rawal Allata of Mewar, it has an inscription of 961 AD recording a repair. It is an early example of Maru-Gurjara architecture.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Maharana Pratap Airport","nearest_airport_distance_km":36.7,"nearest_railway_station_name":"Padla railway station","nearest_railway_distance_km":7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Ambika Mata Temple), summarised; location via OpenStreetMap","architecture_style":"Maru-Gurjara","construction_century":10},{"id":"24579bc9-23b9-4690-9994-08720a0b04aa","name":"Vallakottai Subramaniyaswami temple","deity":"Murugan as Subramaniyaswami","sampradaya":"Kaumara","significance":[],"country":"India","state":"Tamil Nadu","district":"Chennai Metropolitan Area","town":"Vallakkottai","latitude":12.88361,"longitude":79.93333,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Adyar River","river_distance_km":6.9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:59.708182+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Murugan temple at Vallakottai on the Sriperumbudur-Singaperumalkoil road, Tamil Nadu, built in Tamil Hindu style with a gateway, pillared hall and sanctum. Five daily rituals and many yearly festivals are held, the Adi Pooram being the most prominent. The state endowment board maintains it.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Open 6:30 am to 12:00 pm and 5 to 8:30 pm.","accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":28.1,"nearest_railway_station_name":"Pazhaya Seevaram railway station","nearest_railway_distance_km":13.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Vallakottai Subramaniyaswami temple), summarised; location via OpenStreetMap","architecture_style":"Tamil","construction_century":null},{"id":"246d7d8a-33d0-4a71-85f1-20e792469671","name":"Kal Bhairav Temple, Ujjain","deity":"Kal Bhairav (fierce guardian form of Shiva)","sampradaya":"Shaiva","significance":["Tantric shrine"],"country":"India","state":"Madhya Pradesh","district":"Ujjain","town":"Ujjain","latitude":23.21817,"longitude":75.76862,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Shipra","river_distance_km":0.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T09:07:42.20596+00:00","updated_at":"2026-09-22T09:07:42.20596+00:00","sthala_purana":"The present structure stands over an older temple whose founding is attributed, in the Avanti Khanda of the Skanda Purana, to a semi-legendary king named Bhadrasen — a scriptural/legendary claim, not independently documented history. Sculptures of Shiva, Parvati, Vishnu and Ganesha from the Paramara period (9th–13th century) have been recovered on site, which is archaeologically documented; the temple's original walls carried Malwa-style paintings, now largely faded. The structure standing today reflects a Maratha-era reconstruction, restored by Mahadaji Shinde after the Third Battle of Panipat (1761) — an exact restoration date beyond \"post-1761\" wasn't found.","etiquette_notes":"Devotees traditionally offer liquor as prasad here, one of the tantric panchamakara offerings distinctive to this temple — roughly a third is returned as blessed prasad. This is a normal, central part of worship at this specific temple, not an aberration, and visitors unfamiliar with the practice should expect it.","native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Approximate daily hours, per local tourism sources rather than an official schedule: roughly 5am–10pm, with darshan paused briefly during the ~8am and ~8:30pm aartis.","accessibility_notes":null,"nearest_airport_name":"Devi Ahilyabai Holkar Airport, Indore","nearest_airport_distance_km":60,"nearest_railway_station_name":"Ujjain Junction","nearest_railway_distance_km":7,"emergency_contact_notes":null,"sthala_purana_source":"Skanda Purana, Avanti Khanda (legendary); archaeological finds; Maratha-era records","architecture_style":"Maratha style, with a Deepmalika (lamp tower); Paramara-period sculptures recovered on site","construction_century":18},{"id":"2474255d-9005-4597-ba41-79e2727cdc0e","name":"Bijasan Mata Temple, Indragarh","deity":"Durga as Bijasan Mata","sampradaya":"Shakta","significance":[],"country":"India","state":"Rajasthan","district":"Bundi","town":"Indragarh","latitude":25.73292,"longitude":76.16594,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kar Khal River","river_distance_km":4.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:59.639499+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A cave temple in the Aravalli hills near Indragarh in Bundi district, said to be over two thousand years old. According to tradition, Durga slew the demon Raktabija and then sat upon him as a seat, giving her the name Bijasan. Devotees visit in very large numbers each year.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kota Airport","nearest_airport_distance_km":71.3,"nearest_railway_station_name":"Indragarh Sumerganj Mandi railway station","nearest_railway_distance_km":6.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Bijasan Mata Temple, Indragarh), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2491e785-35d4-49df-abbb-127367a266b3","name":"Champakesvara Siva Temple","deity":"Shiva as Champakesvara","sampradaya":"Shaiva","significance":[],"country":"India","state":"Odisha","district":"Khordha","town":"Bhubaneswar Municipal Corporation","latitude":20.24667,"longitude":85.85778,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dayaa River","river_distance_km":4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:38.196668+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A laterite Shiva temple in the Ambika Sahi area of Old Town Bhubaneswar, west of Parasuramesvara. Locals believe the lingam is self-emerged from the earth and that the precinct is home to champa nagas, after whom the deity is named. They also believe the snakes living here do not harm anyone.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":4.7,"nearest_railway_station_name":"Bhubaneswar railway station","nearest_railway_distance_km":2.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Champakesvara Siva Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"24c78b24-902f-4d1a-95b6-a9e254d2ed83","name":"Chamunda Devi Temple, Rudraprayag","deity":"Chamunda (Devi)","sampradaya":"Shakta","significance":["Panch Prayag"],"country":"India","state":"Uttarakhand","district":"Rudraprayag","town":"Rudraprayag","latitude":30.28,"longitude":78.98,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Alaknanda–Mandakini confluence","river_distance_km":0.1,"best_season_notes":"Mar–Jun and Sep–Nov.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T11:22:57.994564+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"The fourth of the Panch Prayag, where the Mandakini flowing down from Kedarnath joins the Alaknanda flowing down from Badrinath. Chamunda, worshipped here as consort of Rudra (Shiva), gives the confluence its name. Tradition holds that the sage Narada meditated at this sangam and received the art of music from Shiva.","etiquette_notes":null,"native_name":"चामुंडा देवी मंदिर, रुद्रप्रयाग","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Dehradun Airport","nearest_airport_distance_km":77.3,"nearest_railway_station_name":null,"nearest_railway_distance_km":null,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":null},{"id":"24fef099-2b8b-4bc5-b211-e523ffee24ee","name":"Krishna Janmabhoomi Temple, Mathura","deity":"Krishna","sampradaya":"Vaishnava","significance":["Sapta Puri"],"country":"India","state":"Uttar Pradesh","district":"Mathura","town":"Mathura","latitude":27.5042,"longitude":77.6737,"sandhya_friendly":"yes","sandhya_notes":"The Yamuna and its ghats are a short walk away.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Yamuna","river_distance_km":1,"best_season_notes":"Oct–Nov and Feb–Mar sidestep the Dec–Jan fog that regularly delays road and rail travel around Mathura; Janmashtami (Aug/Sept) and Holi are extremely crowded if you want the festival atmosphere instead.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-05T18:23:31.36475+00:00","sthala_purana":"Held by tradition to be the exact site of the prison cell where Krishna was born to Devaki and Vasudeva, under the tyranny of Devaki's brother, King Kamsa. The site has been rebuilt and re-consecrated many times over the centuries; the present temple complex stands immediately beside the Shahi Idgah, and both sit within what is revered as the same ancient birthplace precinct.","etiquette_notes":null,"native_name":"श्री कृष्ण जन्मभूमि मन्दिर","morning_opens_at":"05:30:00","morning_closes_at":"12:00:00","evening_opens_at":"16:00:00","evening_closes_at":"20:30:00","timings_notes":"Shifts by roughly 30–60 minutes with the season and on Ekadashi; sources disagree slightly, so confirm locally.","accessibility_notes":null,"nearest_airport_name":"Agra Airport","nearest_airport_distance_km":60,"nearest_railway_station_name":"Mathura Junction","nearest_railway_distance_km":3,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":null,"construction_century":null},{"id":"255ee888-bfc0-426d-a7ef-d299b83ef375","name":"Galteshwar Temple","deity":"Shiva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Gujarat","district":"Kheda","town":"Galteshwar Taluka","latitude":22.78504,"longitude":73.27749,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Mahi River","river_distance_km":0.5,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:47.875457+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Galteshwar is a twelfth-century Shiva temple at Sarnal village near Dakor in Kheda district, Gujarat. It is considered distinctive for combining the central Indian Malwa bhumija style with Gujarati Chaulukya influence, without Paramara influence. It has a square sanctum and an octagonal mandapa.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vadodara Green Airport Harni","nearest_airport_distance_km":50.2,"nearest_railway_station_name":"Angadi railway station","nearest_railway_distance_km":2.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Galteshwar Temple), summarised; location via OpenStreetMap","architecture_style":"Bhumija (Malwa) with Chaulukya influence","construction_century":12},{"id":"259b2fc9-5f57-4785-a8c0-e718f7cb4ad0","name":"Neelkanth temple, Alwar district","deity":"Shiva as Neelkanth","sampradaya":"Shaiva","significance":[],"country":"India","state":"Rajasthan","district":"Alwar","town":"Dabkan","latitude":27.24741,"longitude":76.35197,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Sanwan River","river_distance_km":5.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:24.13334+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva temple on an isolated hill near Sariska National Park, reached only by a steep track. It was built between the 6th and 9th centuries by a local Pratihara feudatory, Parmeshwara Mathanadeva.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Jaipur International Airport","nearest_airport_distance_km":70.4,"nearest_railway_station_name":"Baswa railway station","nearest_railway_distance_km":24.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Neelkanth temple, Alwar district), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":8},{"id":"25a8e2df-7992-440a-b55a-ae5724b1ca1c","name":"Mahalakshmi Temple, Mumbai","deity":"Mahalakshmi","sampradaya":"Shakta","significance":[],"country":"India","state":"Maharashtra","district":"Mumbai City","town":"D Ward","latitude":18.9774,"longitude":72.8065,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"ganga River","river_distance_km":1.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:44.755986+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of Mumbai's best-known temples, dedicated to Mahalakshmi, the central goddess of the Devi Mahatmyam. The merchant Dhakji Dadaji built it in 1831. It contains images of the three goddesses Mahakali, Mahalakshmi and Mahasaraswati.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chhatrapati Shivaji Maharaj International Airport","nearest_airport_distance_km":13.9,"nearest_railway_station_name":"Mumbai Central railway station","nearest_railway_distance_km":1.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mahalakshmi Temple, Mumbai), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":19},{"id":"25d3bdfd-0171-4708-8f7e-4358cbc67403","name":"Rudranath Temple","deity":"Shiva (Rudranath)","sampradaya":"Shaiva","significance":["Panch Kedar"],"country":"India","state":"Uttarakhand","district":"Chamoli","town":"Gopeshwar","latitude":30.53333,"longitude":79.33333,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Mena Nadi River","river_distance_km":2.5,"best_season_notes":"Open only in the warmer months (roughly May–Oct); the trek — around 20 km from Sagar village near Gopeshwar — is considered the most demanding of the Panch Kedar circuit.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T08:35:20.91066+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"The fourth of the Panch Kedar temples, where tradition holds Shiva's face (mukh) surfaced after the Pandavas' search for him following the Mahabharata war — his other body parts are worshipped at the other four Panch Kedar shrines. Local belief holds that Shiva's full body is worshipped at Pashupatinath in Kathmandu, while only the face is enshrined here, in his fierce Rudra form.","etiquette_notes":null,"native_name":"रुद्रनाथ मंदिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Dehradun Airport","nearest_airport_distance_km":116.8,"nearest_railway_station_name":null,"nearest_railway_distance_km":null,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":null},{"id":"2602793f-a164-492b-a624-5575a1892182","name":"Jagannath Temple, Alwar","deity":"Vishnu as Jagannath","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Rajasthan","district":"Alwar","town":"Alwar Tehsil","latitude":27.53058,"longitude":76.60381,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":null,"river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:03:56.940052+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"A Vishnu temple in the old part of Alwar whose presiding deity is Jagannath, with Sitaramji and Jankiji also installed. The sanctum holds two Jagannath images, one movable and one fixed. Its Rath Yatra uses a former royal elephant carriage as the chariot and is tied to a wedding celebration, differing from Puri's customs.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Jaipur International Airport","nearest_airport_distance_km":110.1,"nearest_railway_station_name":"Alwar Junction railway station","nearest_railway_distance_km":3.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Jagannath Temple, Alwar), summarised; location via OpenStreetMap","architecture_style":"Medieval","construction_century":null},{"id":"262151f5-ff7e-43c4-8ab9-96f96b1cb6cf","name":"Amreshwar Dham","deity":"Shiva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Jharkhand","district":"Khunti","town":"Murhu","latitude":23.03083,"longitude":85.19944,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Chingairjhor River","river_distance_km":4.8,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:54.58588+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva temple complex near Khunti, Jharkhand, about 45 km from Ranchi, renamed by Swami Swarupananda Saraswati. Shrines to Ganesha, Rama, Sita and Hanuman stand on the site, and crowds gather in Sawan and at Maha Shivaratri.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Ranchi Birsa Munda Airport","nearest_airport_distance_km":34,"nearest_railway_station_name":"Karra railway station","nearest_railway_distance_km":12.2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Amreshwar Dham), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2644cc9d-fee0-44a1-9741-8f92f49d2769","name":"Dwarkadhish Temple, Dwarka","deity":"Krishna (Dwarkadhish)","sampradaya":"Vaishnava","significance":["Char Dham","Sapta Puri"],"country":"India","state":"Gujarat","district":"Devbhoomi Dwarka","town":"Dwarka","latitude":22.2442,"longitude":68.9685,"sandhya_friendly":"yes","sandhya_notes":"Gomti Ghat, a short walk from the temple, is the traditional bathing spot.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Dwarkadhish Temple prasad counter (puri-sabzi thali and sweets)","food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Gomti (confluence with the Arabian Sea)","river_distance_km":0.3,"best_season_notes":"Oct–Mar; can be paired with Nageshwar Jyotirlinga and Beyt Dwarka.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-04T11:30:32.947142+00:00","sthala_purana":"Dwaraka is described as the city Krishna built after leaving Mathura, raised from land reclaimed from the sea, and submerged again after his departure from the world. The temple is called Jagat Mandir, and its shrine is entered by the Swarga Dwara and left by the Moksha Dwara.","etiquette_notes":null,"native_name":"द्वारकाधीश मन्दिर","morning_opens_at":"06:30:00","morning_closes_at":"13:30:00","evening_opens_at":"17:30:00","evening_closes_at":"21:30:00","timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Jamnagar Airport","nearest_airport_distance_km":137,"nearest_railway_station_name":"Dwarka Railway Station","nearest_railway_distance_km":2,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":"Nagara","construction_century":16},{"id":"267d97fa-d82c-4a10-8f9c-096af2a9243c","name":"Kottukal Cave Temple","deity":"Ganapathy","sampradaya":"Ganapatya","significance":[],"country":"India","state":"Kerala","district":"Kollam","town":"Kottukkal","latitude":8.88958,"longitude":76.90525,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"ithikkara River","river_distance_km":2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A rock-cut temple near Anchal, dated between the 6th and 8th centuries, with two east-facing caves and Ganapathy as the main sculpture. The smaller cave holds Hanuman, and the larger a monolithic Nandi; a Shiva lingam is also present. Historians credit a ruler of Chadayamangalam. Travancore Devaswom Board handles daily rituals.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Thiruvananthapuram International Airport","nearest_airport_distance_km":45.4,"nearest_railway_station_name":"Punalur railway station","nearest_railway_distance_km":14.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Kottukal Cave Temple), summarised; location via OpenStreetMap","architecture_style":"Rock-cut","construction_century":7},{"id":"26aaccd5-ea65-4b2c-90e2-a7ff4ee075c3","name":"Rameshvara Temple, Koodli","deity":"Shiva as Rameshvara","sampradaya":"Shaiva","significance":[],"country":"India","state":"Karnataka","district":"Shimoga","town":"Kudli","latitude":14.00681,"longitude":75.67458,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Tunga and Bhadra confluence","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"A 12th-century Hoysala Shiva temple in Kudli, built of soapstone in a plain Vesara style. It has three entrances, a single vimana and an open mantapa. Kudli lies where tributaries of the Tungabhadra meet and has ruins of several other temples and monasteries. The temple is a nationally protected monument.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Shivamogga Airport","nearest_airport_distance_km":17.6,"nearest_railway_station_name":"Shimoga Bidare railway station","nearest_railway_distance_km":12,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Rameshvara Temple, Koodli), summarised; location via OpenStreetMap","architecture_style":"Hoysala, Vesara","construction_century":12},{"id":"2700994b-c58b-4b6a-ac72-15019d860d58","name":"Bhagyalakshmi Temple","deity":"Bhagyalakshmi","sampradaya":"Shakta","significance":[],"country":"India","state":"Telangana","district":"Hyderabad","town":"Hyderabad","latitude":17.36139,"longitude":78.47444,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Musi River","river_distance_km":1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:05:20.030396+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A small shrine to the goddess Bhagyalakshmi beside the Charminar in Hyderabad, run by a Hindu trust. Its origin is disputed, and the present structure housing the idol dates from the 1960s. The High Court halted expansion in 2012, and in 2013 the ASI called the structure unauthorised.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Begumpet Airport","nearest_airport_distance_km":10.3,"nearest_railway_station_name":"Shah Ali Banda Metro railway station","nearest_railway_distance_km":0.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Bhagyalakshmi Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2714d147-3ac0-4656-8ba9-f3cb3ee0560c","name":"Tulsi Manas Mandir","deity":"Rama","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Uttar Pradesh","district":"Varanasi","town":"Varanasi","latitude":25.28721,"longitude":83.00042,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Assi River","river_distance_km":0.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:10:09.085477+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A well-known temple in Varanasi tied to the poet-saint Tulsidas. The article says the epic Ramcharitmanas was first composed at this spot, in the 16th century, which gives the place deep cultural and religious importance.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Lal Bahadur Shastri International Airport","nearest_airport_distance_km":22.9,"nearest_railway_station_name":"Banaras (Manduadih) railway station","nearest_railway_distance_km":3.2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Tulsi Manas Mandir), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2726d8e0-abe4-46d7-8924-7eeb6d0f4969","name":"Thillai Nataraja Temple, Chidambaram (Akasha Sthalam)","deity":"Shiva (Nataraja)","sampradaya":null,"significance":["Pancha Bhoota Sthalam","Pancha Sabhai"],"country":"India","state":"Tamil Nadu","district":"Cuddalore","town":"Chidambaram","latitude":11.3994,"longitude":79.6936,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Nithyam Annam Trust — serves free sattvic meals (rice, sambar, kootu, rasam, vadai) to pilgrims daily in Chidambaram town","food_source_contact":null,"food_distance_km":0.5,"nearest_river_name":"Uppanru River","river_distance_km":2.5,"best_season_notes":"Dec–Mar; the Natyanjali dance festival (Feb/Mar) is a major cultural draw. Chidambaram sits on the Tamil Nadu coast, directly in the path of the Oct–Nov northeast monsoon and occasional cyclones, worth avoiding if the itinerary allows.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Shiva is worshipped here as Nataraja, performing the Ananda Tandava in the golden hall. The Chidambara Rahasya, behind a curtain beside the image, is empty space — the ether element among the Pancha Bhoota Sthalams, and a teaching that the divine is not confined to form.","etiquette_notes":null,"native_name":"தில்லை நடராஜர் கோயில்","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Neyveli Airport","nearest_airport_distance_km":29.9,"nearest_railway_station_name":"Chidambaram railway station","nearest_railway_distance_km":1.3,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":"Dravidian","construction_century":17},{"id":"27986792-5586-4a99-b245-90579426cd87","name":"Kalighat Kali Temple","deity":"Kali (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"West Bengal","district":"Kolkata","town":"Kalighat","latitude":22.5193,"longitude":88.3425,"sandhya_friendly":"no","sandhya_notes":"Dense urban setting with no dedicated quiet space known near the temple for Sandhya Vandanam.","samidhadhanam_friendly":"no","samidhadhanam_notes":"Not feasible in this dense urban temple setting.","food_tier":"pure_veg_available","food_source_name":"Bhawanipur pure-veg Brahmin mess (10 min drive)","food_source_contact":"+91-98300-12345","food_distance_km":2.5,"nearest_river_name":"Adi Ganga (Hooghly tributary)","river_distance_km":0.2,"best_season_notes":"Dec–Feb; the temple and surrounding lanes are very crowded year-round, so plan for a long queue regardless of season. Kolkata's main storm risk falls in Oct–Nov, same as the rest of the Bengal coast.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-05T18:23:31.36475+00:00","sthala_purana":"One of the Shakti Peethas: when Shiva carried Sati's body across the world in grief, Vishnu's discus severed it, and the parts fell at fifty-one places. The toes of her right foot are said to have fallen here, at the Adi Ganga.","etiquette_notes":null,"native_name":"কালীঘাট কালীমন্দির","morning_opens_at":"05:00:00","morning_closes_at":"14:00:00","evening_opens_at":"17:00:00","evening_closes_at":"22:30:00","timings_notes":"Closed roughly 2–5pm for Bhog; some sources cite a shorter 1–3pm break instead.","accessibility_notes":null,"nearest_airport_name":"Netaji Subhas Chandra Bose International Airport, Kolkata","nearest_airport_distance_km":15,"nearest_railway_station_name":"Kalighat Metro Station","nearest_railway_distance_km":1,"emergency_contact_notes":null,"sthala_purana_source":"Devi Bhagavata Purana / Shakti Peetha tradition (Sati-limb legend)","architecture_style":null,"construction_century":null},{"id":"27e5d336-253e-4aab-a43b-bf3c76cfc3e8","name":"Mahasu Devta Temple","deity":"Shiva as Mahasu Devta","sampradaya":"Shaiva","significance":[],"country":"India","state":"Uttarakhand","district":"Dehradun","town":"Chatra","latitude":30.971,"longitude":77.92795,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Tons","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"A temple at Hanol on the Tons river in Jaunsar, dedicated to Shiva as Mahasu Devta. Only the original sanctum survives, topped by a curved Nagara shikhara dated to the 9th-10th century; the halls were added later. The stone and wood building follows the Kath Kuni style and is on the ASI list of ancient temples.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Shimla Airport","nearest_airport_distance_km":83,"nearest_railway_station_name":null,"nearest_railway_distance_km":null,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mahasu Devta Temple), summarised; location via OpenStreetMap","architecture_style":"Nagara with Kath Kuni","construction_century":9},{"id":"283b9dff-b670-4f49-9921-60224813dd45","name":"Shri Mahaveer Hanuman Mandir Khushala","deity":"Hanuman","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Himachal Pradesh","district":"Shimla","town":"Shogi","latitude":31.0525,"longitude":77.11417,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Gambhar River","river_distance_km":2.9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Shri Mahaveer Hanuman Mandir, also called Thakurdwara, is a Hanuman temple in Khushala village in the Shoghi area of Shimla, Himachal Pradesh. It is popular with locals and tourists.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Shimla Airport","nearest_airport_distance_km":5.6,"nearest_railway_station_name":"Shoghi railway station","nearest_railway_distance_km":1.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Shri Mahaveer Hanuman Mandir Khushala), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"284094e3-2bd6-4d5a-946e-64d38a80f02c","name":"Mahakala-Mahakali Temple","deity":"Shiva as Mahakala and Mahakali","sampradaya":"Shaiva","significance":[],"country":"India","state":"Odisha","district":"Khordha","town":"Bhubaneswar Municipal Corporation","latitude":20.23761,"longitude":85.83431,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dayaa River","river_distance_km":2.9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:05:32.681015+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An 11th-century open-roofed shrine without a superstructure, just east of the Lingaraja temple compound in Bhubaneswar. A lingam on a yonipitha, about four metres below ground level, is called Mahakala and a smaller one Mahakali. Local tradition calls them the parents of Lingaraja.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":2.8,"nearest_railway_station_name":"Bhubaneswar railway station","nearest_railway_distance_km":3.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mahakala-Mahakali Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":11},{"id":"28a47622-7bed-46ea-b6a7-953d5fd4a0e1","name":"Chengannur Mahadeva Temple","deity":"Mahadeva-Parvati (Shiva-Parvati)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Kerala","district":"Alappuzha","town":"Chengannur","latitude":9.3167,"longitude":76.6167,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pamba River","river_distance_km":1.1,"best_season_notes":"Nov–Dec, though the temple's Thripoot rite can fall in other months depending on the deity's own cycle.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T17:30:52.99453+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Believed to have been built over 1,500 years ago by the legendary architect Perunthachan, and unusual in Kerala for enshrining Shiva and Parvati as a married couple in one sanctum. Tradition holds this is where the couple, travelling to meet sage Agastya after their wedding, paused when Parvati menstruated — the basis for the temple's distinctive Thripoot festival, during which the sanctum closes for several days each cycle and reopens with elaborate rites, a practice with few parallels outside Kamakhya.","etiquette_notes":null,"native_name":"ചെങ്ങന്നൂർ മഹാദേവക്ഷേത്രം","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":96.1,"nearest_railway_station_name":"Chengannur railway station","nearest_railway_distance_km":0.9,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":6},{"id":"28fc0dcf-f7c7-4f3b-a84b-df1508fd1e98","name":"Badami Banashankari Temple","deity":"Banashankari","sampradaya":"Pooja is done by Smarthas","significance":["Shakti Peetha"],"country":"India","state":"Karnataka","district":"Bagalakote","town":"Badami","latitude":15.885034,"longitude":75.705339,"sandhya_friendly":"yes","sandhya_notes":"You can sit in the Right side of the devi in the courtyard for Sandhya","samidhadhanam_friendly":"yes","samidhadhanam_notes":"Please carry the homa kunda of small size and request that you never skip Samidhadhanam ,  they will allow, I have done all the times when I went there, just be mindful of cleaning the place after  the Samidhadhanam is done","food_tier":"brahmin_run_kitchen","food_source_name":"Food Is available as prasadam, but it's paid one, a generic kitchen is also present for all the castes which is free, only lunch is  served","food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Malaprabha River","river_distance_km":1.3,"best_season_notes":"Avoid  in summer, In full moon day the temple might  get busy","submitted_by":"196e6d0a-a7d5-4894-bfdb-e96ff585593d","status":"approved","verified_by":"8049c1cb-e6d2-4d7b-88ce-d35ba2cdd2e8","moderator_note":null,"created_at":"2026-09-05T06:06:51.934092+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"According to the Skanda Purana and Padma Purana, the demon Durgamasura tormented the region until the goddess Shakambari — worshipped here as Banashankari, an incarnation of Parvati — emerged from a sacrificial fire to slay him and restore peace. A separate local tradition holds she later appeared in a dream to a Chalukya king, instructing him to build a temple in her honour. Banashankari became the kuladevata (family deity) of the Kalyana Chalukyas; the original shrine here, built by the 7th-century Badami Chalukyas, was later rebuilt in 1750 CE.","etiquette_notes":null,"native_name":"ಬಾದಾಮಿ ಬನಶಂಕರಿ ದೇವಸ್ಥಾನ","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Hubballi Airport","nearest_airport_distance_km":89,"nearest_railway_station_name":"Lakhmapur railway station","nearest_railway_distance_km":8.5,"emergency_contact_notes":null,"sthala_purana_source":"Skanda Purana, Padma Purana, and local/regional tradition","architecture_style":"Chalukya","construction_century":null},{"id":"290f473e-0752-47d4-832b-b76f466ab6c0","name":"Panchamuka Anjaneyar Temple, Gowrivakkam","deity":"Panchamukha Anjaneyar (five-faced Hanuman)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Tamil Nadu","district":"Chennai","town":"Gowrivakkam","latitude":12.905,"longitude":80.168,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Okkiyam Maduvu River","river_distance_km":6.7,"best_season_notes":"Nov–Feb, or around Hanuman Jayanti.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-08T06:51:40.218447+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Gowrivakkam shrine near the SIVET College campus, enshrining the five-faced (Narasimha, Garuda, Varaha, Hayagriva, and Hanuman-faced) form of Hanuman.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":9.8,"nearest_railway_station_name":"Tambaram Sanatorium railway station","nearest_railway_distance_km":5.4,"emergency_contact_notes":null,"sthala_purana_source":"Contributor-submitted local survey","architecture_style":null,"construction_century":null},{"id":"293075bf-0511-4eb9-923b-d3e5a23c02b3","name":"Chakkulathukavu Temple","deity":"Durga","sampradaya":"Shakta","significance":[],"country":"India","state":"Kerala","district":"Alappuzha","town":"Thalavady","latitude":9.3669,"longitude":76.5142,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pampa","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T10:59:23.880063+00:00","updated_at":"2026-11-04T12:15:48.914317+00: