km":22.2,"nearest_railway_station_name":"Bihta railway station","nearest_railway_distance_km":2.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Van Devi Temple, Bihta), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2a826690-22b8-47d9-82e3-ba85954c2a44","name":"Sri Dakshinamukha Nandi Tirtha Kalyani Kshetra","deity":"Shiva (lingam)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Karnataka","district":"Bengaluru Urban","town":"Bengaluru","latitude":13.00505,"longitude":77.57316,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vrishabhavati","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:38.196668+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"A small Shiva temple in Malleswaram, Bangalore, also called Nandi Tirtha or the Malleswaram Nandi gudi. Its main deity is a Shiva lingam. The temple was reportedly found again in 1997 after being buried for about 400 years, and it is described as the holy source of the Vrishabhavati river.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kempegowda International Airport","nearest_airport_distance_km":25.8,"nearest_railway_station_name":"Malleswaram railway station","nearest_railway_distance_km":1.2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Sri Dakshinamukha Nandi Tirtha Kalyani Kshetra), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2ad6fb1c-bba0-4ea7-b053-531c69964ad4","name":"Varadaraja Perumal Temple, Kanchipuram","deity":"Varadaraja (Vishnu)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Tamil Nadu","district":"Kanchipuram","town":"Kanchipuram","latitude":12.8194,"longitude":79.73,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vegavathy","river_distance_km":1.5,"best_season_notes":"Dec–Mar. One of the 108 Divya Desams, and among the most important Vishnu temples in the Tamil country — like the rest of Kanchipuram, its wettest weeks fall in the Oct–Nov northeast monsoon.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T13:44:40.752775+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Tradition holds that Brahma performed an ashvamedha yajna here, from whose sacrificial fire Vishnu appeared as Varadaraja, \"the boon-granting king\". Ramanujacharya is associated with this temple in his early years.","etiquette_notes":null,"native_name":"வரதராஜப் பெருமாள் கோயில்","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":51.2,"nearest_railway_station_name":"Kanchipuram East railway station","nearest_railway_distance_km":3.1,"emergency_contact_notes":null,"sthala_purana_source":"Naalayira Divya Prabandham (Alvar hymn tradition)","architecture_style":"Dravidian","construction_century":8},{"id":"2b02e259-8906-4bd2-913a-25651842f104","name":"Chausath Yogini Temple, Khajuraho","deity":"Yoginis","sampradaya":"Shakta","significance":[],"country":"India","state":"Madhya Pradesh","district":"Chhatarpur","town":"Khajuraho","latitude":24.84952,"longitude":79.91813,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Khudar River","river_distance_km":1.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:36.374917+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A ruined Yogini temple at Khajuraho, dated to the late 9th century and the oldest surviving temple there. Unlike other Yogini temples it has a rectangular plan, though like them it is open to the sky. It is part of the Khajuraho Group of Monuments, a UNESCO World Heritage Site since 1986.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Khajuraho Airport","nearest_airport_distance_km":4.1,"nearest_railway_station_name":"Khajuraho railway station","nearest_railway_distance_km":6.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Chausath Yogini Temple, Khajuraho), summarised; location via OpenStreetMap","architecture_style":"Chandela","construction_century":9},{"id":"2b13e734-5908-4d6e-a500-d1524667f9ee","name":"Sri Kurmam Temple","deity":"Kurma (Vishnu)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Andhra Pradesh","district":"Srikakulam","town":"Srikurmam","latitude":18.6333,"longitude":84.0833,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Garibula Gedda River","river_distance_km":3.5,"best_season_notes":"Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T13:20:34.20482+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"The only temple in India where Vishnu is worshipped in his Kurma (tortoise) avatar, and one of the few Suyambu (self-manifest) Kurma shrines anywhere. Tradition holds the pious king Sweta Maharaja's long penance drew Vishnu to appear here in this form, with Brahma himself consecrating the shrine; a later telling names king Swetha Chakravarti, guided by the sage Narada. The temple's inscriptional history reaches back to the 11th–12th centuries, and it was restored under the Eastern Ganga king Anantavarman Chodaganga Deva.","etiquette_notes":null,"native_name":"శ్రీకూర్మం ఆలయం","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Alluri Sitarama Raju International Airport","nearest_airport_distance_km":95.1,"nearest_railway_station_name":"Parlakhemundi railway station","nearest_railway_distance_km":16.9,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":null},{"id":"2b17346a-1360-44e8-ba6f-24b18bd011df","name":"Hanuman Tok","deity":"Hanuman","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Sikkim","district":"Gangtok","town":"Gangtok","latitude":27.34778,"longitude":88.62861,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Roro Chu River","river_distance_km":2.1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:10:09.085477+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A temple complex in the upper part of Gangtok, dedicated to Hanuman and looked after by the Indian army. The article says a bureaucrat, Appaji Pant, built the shrine over a stone in 1950, and the army later took over the land around it together with the temple.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Pakyong Airport","nearest_airport_distance_km":13.4,"nearest_railway_station_name":"Darjeeling railway station","nearest_railway_distance_km":49.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Hanuman Tok), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":20},{"id":"2b306c06-6b21-4762-8923-e110e263b646","name":"Mahamaya Devi Temple, Ratanpur","deity":"Mahamaya (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Chhattisgarh","district":"Bilaspur","town":"Ratanpur","latitude":22.2833,"longitude":82.1667,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kharang River","river_distance_km":4.3,"best_season_notes":"Sep–Oct for Navaratri; otherwise Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T17:30:52.99453+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Built under the Kalachuri dynasty of Ratanpur in the 12th–13th centuries and counted among the 52 Shakti Peethas. Tradition holds King Ratnadeva was woken one night by a brilliant light and found the goddess Mahamaya holding court; she later appeared to him in a dream instructing him to move his capital to Ratanpur, promising him fame in return. The temple, originally dedicated to Mahakali, Mahalakshmi and Mahasaraswati together, was rebuilt in its present form devoted to Mahalakshmi and Mahasaraswati in 1492.","etiquette_notes":null,"native_name":"महामाया देवी मन्दिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Bilasa Devi Kevat Airport","nearest_airport_distance_km":33.2,"nearest_railway_station_name":"Kalmitar railway station","nearest_railway_distance_km":12.4,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":"Nagara","construction_century":12},{"id":"2b323e1f-f6da-4c44-a31c-54ced27387b8","name":"Shiva Temple, Bavka","deity":"Shiva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Gujarat","district":"Dahod","town":"Dahod Taluka","latitude":22.75221,"longitude":74.20147,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Hirlav lake","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"This Shiva temple complex lies on a knoll near Hirlav lake between Bavka and Chandavada, about 14 km from Dahod in Gujarat. It dates to roughly the 12th to 13th century and is an example of Maru-Gurjara architecture laid out in the panchayatana plan.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vadodara Green Airport Harni","nearest_airport_distance_km":110.3,"nearest_railway_station_name":"Dahod railway station","nearest_railway_distance_km":11.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Shiva Temple, Bavka), summarised; location via OpenStreetMap","architecture_style":"Maru-Gurjara, panchayatana","construction_century":12},{"id":"2b82c86d-dc1c-4c74-a36d-1b5c7ce49a33","name":"Mandagapattu Temple","deity":"Brahma, Shiva and Vishnu (Trimurti)","sampradaya":null,"significance":[],"country":"India","state":"Tamil Nadu","district":"Viluppuram","town":"E.Mandagapattu","latitude":12.10772,"longitude":79.45664,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Varadaru River","river_distance_km":10.8,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:13:52.370722+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A rock-cut cave temple at Mandagapattu, Viluppuram district, attributed to the Pallava king Mahendravarman I for the trinity of Brahma, Shiva and Vishnu. It is the oldest dated stone shrine in Tamil Nadu and bears the earliest known rock-cut Sanskrit inscription in Grantha script.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Puducherry Airport","nearest_airport_distance_km":41.6,"nearest_railway_station_name":"Perani railway station","nearest_railway_distance_km":10.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mandagapattu Temple), summarised; location via OpenStreetMap","architecture_style":"Rock-cut cave temple","construction_century":7},{"id":"2bcba433-93be-476b-9487-34e4eb156978","name":"Mangala Gauri Temple, Gaya","deity":"Mangala Gauri (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Bihar","district":"Gaya","town":"Gaya","latitude":24.7955,"longitude":85.0002,"sandhya_friendly":"yes","sandhya_notes":"The Falgu river, associated with Gaya's Pitru Paksha rites, is close by.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Falgu","river_distance_km":1.5,"best_season_notes":"Oct–Feb; Pitru Paksha (Sept/Oct) brings large crowds for ancestral rites across Gaya.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"One of the Shakti Peethas, traditionally held to mark where a breast of Sati fell. Its location in Gaya links it to one of the subcontinent's most significant sites for pinda daan (ancestral rites) — pilgrims performing rites for their forebears elsewhere in Gaya customarily visit Mangala Gauri as part of the same pilgrimage.","etiquette_notes":null,"native_name":"मंगला गौरी मन्दिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Gaya International Airport","nearest_airport_distance_km":7.7,"nearest_railway_station_name":"Gaya Junction railway station","nearest_railway_distance_km":0.9,"emergency_contact_notes":null,"sthala_purana_source":"Devi Bhagavata Purana / Shakti Peetha tradition (Sati-limb legend)","architecture_style":null,"construction_century":null},{"id":"2bd298c7-41f2-4b5f-a6c7-16bc1461618c","name":"Dashavatara Temple, Deogarh","deity":"Vishnu","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Uttar Pradesh","district":"Lalitpur","town":"Devgarh","latitude":24.52661,"longitude":78.24011,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Betwa","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:53.924452+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"An early 6th-century Gupta-period stone temple at Deogarh in the Betwa valley, with a simple square one-cell plan and among the earliest surviving Hindu stone temples. It is dedicated to Vishnu and carved with scenes of his legends, along with other deities and secular figures. Though ruined, it is key to the study of north Indian temple architecture.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Guna","nearest_airport_distance_km":91.4,"nearest_railway_station_name":"Jakhalaun railway station","nearest_railway_distance_km":10.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Dashavatara Temple, Deogarh), summarised; location via OpenStreetMap","architecture_style":"Gupta","construction_century":6},{"id":"2c43d30a-855d-4282-bba4-b60c1ddc1f1d","name":"Sri Talpagiri Ranganadha Swamy Temple, Nellore","deity":"Vishnu as Ranganatha","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Andhra Pradesh","district":"Sri Potti Sriramulu Nellore","town":"Udayagiri","latitude":14.87885,"longitude":79.29786,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Penna","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"One of the oldest temples in Nellore, on the Penna river bank, dedicated to Ranganatha, a reclining form of Vishnu, and believed to date from the 12th century. A tall entrance tower called the Gaaligopuram, about 70 feet high with gold-plated finials, was built by Yeragudipati Venkatachalam panthulu. A Brahmotsavam is held yearly in March-April.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kadapa Airport","nearest_airport_distance_km":69.8,"nearest_railway_station_name":null,"nearest_railway_distance_km":null,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Sri Talpagiri Ranganadha Swamy Temple, Nellore), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":12},{"id":"2c4b0cfc-bdb7-4813-86a0-6ad547d8e09b","name":"Kroda Narasimha Temple, Upper Ahobilam","deity":"Kroda Narasimha (Vishnu)","sampradaya":"Vaishnava","significance":["Nava Narasimha"],"country":"India","state":"Andhra Pradesh","district":"Nandyal","town":"Ahobilam","latitude":15.135,"longitude":78.79,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bhavanasini","river_distance_km":0.5,"best_season_notes":"Oct–Feb; the forest trek to Upper Ahobilam is best avoided in peak summer or heavy monsoon.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T19:58:00.742097+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"One of the Nava Narasimha, worshipped here in a boar-faced form (sometimes called Varaha Narasimha), blending Vishnu's Varaha and Narasimha avataras. A separate Lakshmi Narasimha image also has darshan at the same shrine.","etiquette_notes":null,"native_name":"క్రోడ నరసింహ ఆలయం","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kadapa Airport","nearest_airport_distance_km":68.9,"nearest_railway_station_name":"Diguvametta railway station","nearest_railway_distance_km":29.2,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition (Nava Narasimha Kshetra)","architecture_style":null,"construction_century":null},{"id":"2cc726cd-d38b-45d7-84f2-4a4e4e555d74","name":"Talupulamma Temple, Lova","deity":"Talupulamma Thalli","sampradaya":"Shakta","significance":[],"country":"India","state":"Andhra Pradesh","district":"Kakinada","town":"Sitayyapeta","latitude":17.3739,"longitude":82.4955,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Thandava River","river_distance_km":4.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:05:20.030396+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A pilgrimage site in Lova village, Kakinada district, set between the forested hills Darakonda and Teegakonda near Tuni. The presiding deity is the village goddess Talupulamma Thalli, regarded as a granter of wishes. The temple lies about 5 km from Tuni and 20 km from the Vaishnava town of Annavaram.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Rajahmundry Airport","nearest_airport_distance_km":78.6,"nearest_railway_station_name":"Tuni railway station","nearest_railway_distance_km":5.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Talupulamma Temple, Lova), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2d1fafc7-454c-452c-aee6-3167674ad830","name":"Golden Temple, Sripuram, Vellore","deity":"Mahalakshmi","sampradaya":null,"significance":[],"country":"India","state":"Tamil Nadu","district":"Vellore","town":"Vellore","latitude":12.8889,"longitude":79.1147,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Free meals served to visitors on the Sripuram Golden Temple premises","food_source_contact":null,"food_distance_km":0.3,"nearest_river_name":"Palar River","river_distance_km":5.2,"best_season_notes":"Dec–Mar. A modern (2007) temple known for its gold-plated architecture, free entry, and prasadam meal — comfortable to visit most of the year, but Tamil Nadu's northeast monsoon (Oct–Nov) is worth avoiding if possible.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A modern temple, consecrated in 2007 by the Sri Narayani Peedam trust under the guidance of Sri Narayani Amma. Unlike the older sites in this directory, it carries no ancient sthala purana — its significance is contemporary, built around 1,500 sheets of gold covering its towers and ceilings, and a free meal (annadanam) served to every visitor regardless of faith.","etiquette_notes":null,"native_name":"ஸ்ரீபுரம் பொன் கோயில்","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Tirupati Airport","nearest_airport_distance_km":94.7,"nearest_railway_station_name":"Vellore Cantonment railway station","nearest_railway_distance_km":2.8,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition, not a single classical Sanskrit text","architecture_style":"Modern","construction_century":21},{"id":"2d3224f6-5d72-41f4-b8d5-62989cee4b0e","name":"Ramchaura Mandir","deity":"Rama","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Bihar","district":"Vaishali","town":"Hajipur","latitude":25.66667,"longitude":85.21667,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Gandak River","river_distance_km":2.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:53.924452+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Rama temple at Rambhadra in Hajipur, Bihar. According to local folklore Rama visited on his way to Janakpur and left footprints, which are worshipped as the central icon. Rama Navami is celebrated with a small fair, and items excavated from the site are kept at the Patna Museum.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Jayprakash Narayan International Airport","nearest_airport_distance_km":15.4,"nearest_railway_station_name":"Hajipur Junction railway station","nearest_railway_distance_km":3.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Ramchaura Mandir), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"2d4c66a9-6632-4b0c-ba1e-66ae014be1d6","name":"Thriprayar Temple","deity":"Vishnu as Rama","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Kerala","district":"Thrissur","town":"Valapad","latitude":10.41416,"longitude":76.11549,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown"