ury":18},{"id":"2f0391a9-3488-45d0-9873-929065b886b6","name":"Kailasanathar Temple, Rajapathy","deity":"Kailasanathar (Shiva)","sampradaya":"Shaiva","significance":["Nava Kailasam"],"country":"India","state":"Tamil Nadu","district":"Thoothukudi","town":"Rajapathy","latitude":8.63,"longitude":78.02,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Thamirabarani","river_distance_km":0.5,"best_season_notes":"Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T19:44:35.569161+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"The eighth of the Nava Kailasam. A folk tradition links this shrine to Ketu among the nine planets.","etiquette_notes":null,"native_name":"கைலாசநாதர் கோயில், ராஜபதி","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Tuticorin Airport","nearest_airport_distance_km":10.8,"nearest_railway_station_name":"Kurumbur railway station","nearest_railway_distance_km":5.4,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition (Agastya-Romasa Muni legend)","architecture_style":"Dravidian","construction_century":null},{"id":"2f412cf2-42a4-4c1e-9707-97f19b3e927b","name":"Mahalakshmi Temple, Kolhapur","deity":"Mahalakshmi (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Maharashtra","district":"Kolhapur","town":"Kolhapur","latitude":16.6947,"longitude":74.2296,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Anna Prasadam dining hall — free meals daily, roughly noon–3pm; a token is handed out on the way out of the temple","food_source_contact":null,"food_distance_km":0,"nearest_river_name":"Panchganga","river_distance_km":1,"best_season_notes":"Oct–Feb; the Kirnotsav (sunset-ray) festival window in Jan/Feb is a special sight.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-05T19:02:16.315601+00:00","sthala_purana":"The goddess here is worshipped as Mahalakshmi or Ambabai, and the temple is built so that at certain days in the year the setting sun's rays fall directly on the image — the Kirnotsav.","etiquette_notes":null,"native_name":"महालक्ष्मी मन्दिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kolhapur Airport","nearest_airport_distance_km":10,"nearest_railway_station_name":"Kolhapur Railway Station","nearest_railway_distance_km":5,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":"Chalukya style, with later Hemadpanthi-era additions and a Maratha-period renovation under Shivaji","construction_century":7},{"id":"2f819765-e797-4677-825b-e52b5bfb601b","name":"Vighnahar Temple, Ozar","deity":"Vighneshwar / Vighnahar (Ganesha)","sampradaya":"Ganapatya","significance":["Ashtavinayak"],"country":"India","state":"Maharashtra","district":"Pune","town":"Ozar (near Junnar)","latitude":19.19,"longitude":73.92,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kukadi","river_distance_km":0.3,"best_season_notes":"Ganesh Chaturthi (Aug–Sep) is the busiest day; Oct–Feb otherwise for the Ashtavinayak circuit.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T13:05:55.016033+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Tradition holds Ganesha took this form to defeat the demon Vighnasura, who had been disrupting sages' yajnas, on the condition that his own name be invoked at the start of any undertaking to clear obstacles (vighna) — the origin, by this local tradition, of Ganesha's role as remover of obstacles.","etiquette_notes":null,"native_name":"श्री विघ्नहर मंदिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Pune International Airport","nearest_airport_distance_km":67.8,"nearest_railway_station_name":"Talegaon railway station","nearest_railway_distance_km":56.8,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition, drawing on the Ganesha Purana","architecture_style":null,"construction_century":null},{"id":"2fbf29b9-28e3-4318-829e-fe9e72260981","name":"Naina Devi Temple","deity":"Naina Devi (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Himachal Pradesh","district":"Bilaspur","town":"Naina Devi","latitude":31.3287,"longitude":76.5464,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Gobind Sagar (Sutlej reservoir)","river_distance_km":3,"best_season_notes":"Mar–Jun and Sept–Nov avoid both peak heat and monsoon landslide risk on the hill road.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"One of the Shakti Peethas, traditionally held to mark where the eyes (nain) of Sati fell — giving the goddess and the temple their name. Set on a hilltop above Anandpur Sahib, it is one of the most visited of the Himachal peetha circuit, reached today by road or a ropeway.","etiquette_notes":null,"native_name":"नैना देवी मन्दिर","morning_opens_at":"06:00:00","morning_closes_at":"22:00:00","evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Open continuously through the day; live-streamed aarti/darshan runs 4–10am on regular days, and the temple stays open through the night during Navratri.","accessibility_notes":"A hill shrine reached by a flight of steps or a ropeway/cable-car option for those who cannot climb.","nearest_airport_name":"Shimla Airport","nearest_airport_distance_km":56.6,"nearest_railway_station_name":"Anandpur Sahib railway station","nearest_railway_distance_km":11.8,"emergency_contact_notes":null,"sthala_purana_source":"Devi Bhagavata Purana / Shakti Peetha tradition (Sati-limb legend)","architecture_style":null,"construction_century":null},{"id":"2fdb57f2-28c8-4bd7-bb1c-3b05abcb09e1","name":"Shamlaji Temple","deity":"Vishnu, worshipped in Trivikrama form as \"Gadadhar Shamlaji\"","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Gujarat","district":"Aravalli","town":"Shamlaji","latitude":23.6881,"longitude":73.3869,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Meshwo","river_distance_km":0.1,"best_season_notes":"The annual Kartik Purnima fair (Oct–Nov) on the Meshwo riverbank features ritual bathing alongside a trade fair.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T08:50:17.345148+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"The site's religious use significantly predates the present building: the Vishnu sculpture in the main sanctum is estimated to the 7th–8th century, a smaller adjoining shrine holds a 6th-century Shiva sculpture, and the nearby Harishchandrani Chauri temple (9th century) is the oldest intact structure at Shamlaji, which was already an active sculpture-production centre by the 6th century — work from its workshops has been found as far away as Mumbai. The main temple itself likely began in Chaulukya style around the 11th century, but the structure standing today mostly dates to a 15th–16th century rebuilding.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Sardar Vallabhbhai Patel International Airport","nearest_airport_distance_km":102.9,"nearest_railway_station_name":"Lusadiya railway station","nearest_railway_distance_km":3.5,"emergency_contact_notes":null,"sthala_purana_source":"Archaeological and art-historical scholarship","architecture_style":"Chaulukya-style origins (11th century); present structure predominantly 15th–16th century","construction_century":15},{"id":"2fea6de4-37ba-4c40-8ebe-77dc2b067763","name":"Halasuru Someshwara Temple","deity":"Shiva as Someshwara","sampradaya":"Shaiva","significance":[],"country":"India","state":"Karnataka","district":"Bengaluru Urban","town":"Bengaluru","latitude":12.97545,"longitude":77.62423,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vrishabhavathi River","river_distance_km":5.9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of Bengaluru's older temples, dating to the Chola period, with major additions under Hiriya Kempe Gowda II in the late Vijayanagara era. Mahashivaratri, Brahmotsavam and Karthika Somawaram are the main festivals, and free food is served on Mondays. Over 100,000 visitors come at Shivaratri.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kempegowda International Airport","nearest_airport_distance_km":26.2,"nearest_railway_station_name":"Bengaluru East railway station","nearest_railway_distance_km":2.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Halasuru Someshwara Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"30272c65-2236-4ceb-ac6d-4b31af59863f","name":"Shyam Kaka Temple","deity":"Krishna (Shyam)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Madhya Pradesh","district":"Rajgarh","town":"Baldiya","latitude":24.009,"longitude":76.728,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Newaj River","river_distance_km":0.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Krishna temple dating to 1845 in a village of Rajgarh district, near Narsinghgarh. A panel inside shows six Muslim men in prayer, which one author cites as an example of shared religious ground. The temple was heavily looted in the British period and rebuilt in 1987, and some parts remain missing.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Guna","nearest_airport_distance_km":95.3,"nearest_railway_station_name":"Biyavra Rajgarh railway station","nearest_railway_distance_km":20,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Shyam Kaka Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":19},{"id":"30b27d94-bcd3-4357-b5b5-68d1a5e1dd3d","name":"Bakreshwar Temple","deity":"Bakreshwar (Shiva) / Mahishmardini","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"West Bengal","district":"Birbhum","town":"Bakreshwar","latitude":23.887,"longitude":87.377,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Paphara","river_distance_km":0.5,"best_season_notes":"Dec–Feb. The site's hot springs (kunda) are used for ritual bathing year-round; Birbhum is inland, so it is less cyclone-exposed than coastal Bengal but shares the same humid June–September monsoon.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T20:39:31.59741+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Tradition holds this is the spot where the eyebrows (or, by some accounts, the mind) of Sati fell, making it one of the Shakti Peethas. The site is unusual for its cluster of natural hot springs, each traditionally associated with a different deity.","etiquette_notes":null,"native_name":"বক্রেশ্বর মন্দির","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kazi Nazrul Islam Airport","nearest_airport_distance_km":32.2,"nearest_railway_station_name":"Chinpai railway station","nearest_railway_distance_km":8.9,"emergency_contact_notes":null,"sthala_purana_source":"Devi Bhagavata Purana / Shakti Peetha tradition (Sati-limb legend)","architecture_style":null,"construction_century":null},{"id":"30ea3885-be6c-42a3-a6b8-a0cf8121d69f","name":"Kalika Mata Temple, Pavagadh","deity":"Kalika Mata (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Gujarat","district":"Panchmahal","town":"Pavagadh","latitude":22.4833,"longitude":73.5333,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Goma River","river_distance_km":14.4,"best_season_notes":"Sep–Oct for Navaratri, when millions of devotees visit; a ropeway serves the hilltop temple year-round.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T17:30:52.99453+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Set atop Pavagadh Hill within the Champaner-Pavagadh Archaeological Park, a UNESCO World Heritage Site. Tradition holds this is where Sati's left breast (by some accounts, her right foot) fell, making it one of the Shakti Peethas. The site was originally a Jain shrine before Kalika Mata's idol was installed in the 12th century, reportedly by sage Vishwamitra; she is worshipped here as Dakshina Kali through tantric forms of puja.","etiquette_notes":null,"native_name":"પાવાગઢ કાલિકા માતાનું મંદિર","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vadodara Green Airport Harni","nearest_airport_distance_km":35.5,"nearest_railway_station_name":"Champaner Road railway station","nearest_railway_distance_km":15.8,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":"Nagara, on a Jain-era hilltop complex","construction_century":11},{"id":"3258a647-bb53-4a5d-8d90-1309d901dc4f","name":"Niranam Thrikkapaleeswaram Dakshinamurthy Temple","deity":"Shiva as Dakshinamurthy","sampradaya":"Shaiva","significance":[],"country":"India","state":"Kerala","district":"Pathanamthitta","town":"Kadapra","latitude":9.34791,"longitude":76.52859,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pampa","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:59.708182+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"An ancient Shiva temple on the bank of the Pampa river at Niranam, Pathanamthitta, Kerala, built in the Dravidian style. The deity is Shiva as Dakshinamurthy, the teacher of all knowledge, facing east. According to folklore the sage Parasurama installed the image, and it is one of the 108 Shiva temples of Kerala.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":90.7,"nearest_railway_station_name":"Thiruvalla railway station","nearest_railway_distance_km":7.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Niranam Thrikkapaleeswaram Dakshinamurthy Temple), summarised; location via OpenStreetMap","architecture_style":"Dravidian","construction_century":null},{"id":"330fd583-f72a-46d3-89f0-08e110879581","name":"Ernakulam Shiva Temple","deity":"Shiva as Ernakulathappan","sampradaya":"Shaiva","significance":[],"country":"India","state":"Kerala","district":"Ernakulam","town":"Ernakulam","latitude":9.96853,"longitude":76.28244,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Edakochi Kayal River","river_distance_km":0.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:03:56.940052+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"The Ernakulathappan temple, a major Shiva temple in the centre of Kochi, regarded locally as the protector of the city. It was one of seven royal temples of the Kochi Maharajas and reached its present form in 1846 under Diwan Edakkunni Sankara Warrier. It stands on about one acre and is managed by the Cochin Devaswom Board.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":24.5,"nearest_railway_station_name":"Ernakulam Junction railway station","nearest_railway_distance_km":0.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Ernakulam Shiva Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":19},{"id":"333c396c-0533-455f-bc37-f809e8c39c76","name":"Peddintlamma Temple, Kolletikota","deity":"Peddintlamma","sampradaya":"Shakta","significance":[],"country":"India","state":"Andhra Pradesh","district":"Eluru","town":"Kolletikota","latitude":16.6276,"longitude":81.2893,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kolleru Lake","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Peddintlamma Temple is a Hindu pilgrimage site on the shore of Kolleru Lake at Kolletikota in Eluru district, Andhra Pradesh. It was built in the 13th century by a general of the Eastern Ganga dynasty during the reign of Narasingha Deva I.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vijayawada Airport","nearest_airport_distance_km":52.8,"nearest_railway_station_name":"Pallevada railway station","nearest_railway_distance_km":5.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Peddintlamma Temple, Kolletikota), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":13},{"id":"334b4145-cf55-4d2e-bfd0-6bb9bc4ee3ab","name":"Banke Bihari Temple, Vrindavan","deity":"Banke Bihari — a united form of Radha and Krishna, in tribhanga (three-bend) posture, worshipped as a child form","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Uttar Pradesh","district":"Mathura","town":"Vrindavan","latitude":27.57976,"longitude":77.69051,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Yamuna River","river_distance_km":0.4,"best_season_notes":"Janmashtami, Radhashtami, Holi, Sharad Purnima (when the deity holds a flute) and Kartik Purnima are the major festivals; the deity is placed on a swing for one day during Shravan.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T10:01:49.265512+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Originally worshipped by Swami Haridas at nearby Nidhivan under the name Kunj Bihari — devotional tradition rather than documented history. The present temple building dates to around 1862–1864, when the murti was moved to its current site, reportedly amid disputes between sadhu and goswami followers.","etiquette_notes":"Darshan here is unusual: there is no continuous open view of the deity — a curtain is opened and closed every few minutes, traditionally so his gaze doesn't linger on any one devotee for too long.","native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Per tourism sources, not an official temple schedule: roughly 7:45am–12pm and 5:30–9:30pm in summer (Mar–Oct), 8:45am–1pm and 4:30–8:30pm in winter (Nov–Feb). Shringar Aarti around 8–9am, Rajbhog Aarti 11am–12pm.","accessibility_notes":"Very crowded, narrow lanes around the temple; a \"Banke Bihari Corridor\" project for ramps and improved wheelchair access is under development but not yet complete.","nearest_airport_name":"Agra (Kheria) Airport","nearest_airport_distance_km":55,"nearest_railway_station_name":"Mathura Junction","nearest_railway_distance_km":14,"emergency_contact_notes":null,"sthala_purana_source":"Devotional tradition (Swami Haridas); temple construction records","architecture_style":"Rajasthani style, completed around 1862","construction_century":19},{"id":"33658b59-0eba-4426-9548-75791b1b95c9","name":"Bagalamukhi Temple, Himachal Pradesh","deity":"Bagalamukhi (Peetambhara)","sampradaya":"Shakta","significance":[],"country":"India","state":"Himachal Pradesh","district":"Kangra","town":"Bankhandi","latitude":31.968,"longitude":76.207,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Beas River","river_distance_km":6.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:36.374917+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A temple at Bankhandi in Kangra district, also known as Anjna Mata Temple, dedicated to Bagalamukhi, one of the ten Tantric Mahavidyas. The goddess, called Peetambhara, is linked with the colour yellow and is shown on a golden throne with three eyes, symbolising her power to grant knowledge.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kangra Airport, Gaggal","nearest_airport_distance_km":22.5,"nearest_railway_station_name":"Jawalamukhi Road railway station","nearest_railway_distance_km":5.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Bagalamukhi Temple, Himachal Pradesh), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"3367602d-5c81-4caf-9195-cf8f5cec0116","name":"Chintamanisvara Siva Temple","deity":"Shiva (lingam)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Odisha","district":"Khordha","town":"Bhubaneswar Municipal Corporation","latitude":20.25,"longitude":85.83889,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dayaa River","river_distance_km":4.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:38.196668+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A west-facing Shiva temple in Bhubaneswar, near the Old Station Bazar, whose sanctum holds a lingam with a yonipitha. It is dated to the 14th century, and local legend credits the Kesharis (Somavamsis) with building it. Shivaratri, Siva vivaha and rudrabhisheka are observed here, and marriages and thread ceremonies are held.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":2.7,"nearest_railway_station_name":"Bhubaneswar railway station","nearest_railway_distance_km":1.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Chintamanisvara Siva Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":14},{"id":"336d5c4e-1fd9-4f25-9c90-996ccd867bd0","name":"Arunachaleswarar Temple, Thiruvannamalai (Agni Sthalam)","deity":"Shiva (Arunachaleswarar)","sampradaya":null,"significance":["Pancha Bhoota Sthalam"],"country":"India","state":"Tamil Nadu","district":"Tiruvannamalai","town":"Thiruvannamalai","latitude":12.2253,"longitude":79.0747,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Temple Annadhanam Hall and nearby ashrams (including Sri Ramanasramam) — free meals, especially valued by those doing the Girivalam circuit","food_source_contact":null,"food_distance_km":0.3,"nearest_river_name":"Oliyar River","river_distance_km":4.5,"best_season_notes":"Dec–Mar avoids Tamil Nadu's northeast-monsoon rains (Oct–Nov); the Karthigai Deepam festival (Nov/Dec) with its hilltop beacon falls right in that wet, very crowded window, so plan for both if attending.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Shiva is said to have appeared here as an infinite column of fire when Brahma and Vishnu contended over who was greater, neither able to find its top or base. The hill itself is worshipped as that column, which is why this is the fire element among the Pancha Bhoota Sthalams; the Karthi