l,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Sheikh ul-Alam International Airport","nearest_airport_distance_km":12.9,"nearest_railway_station_name":"Srinagar railway station","nearest_railway_distance_km":6.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Zeashta Devi Shrine), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"3e639dd6-5049-441b-b57f-c33324f8b4f3","name":"Thoniyakavu Bhadrakali Temple","deity":"Bhadrakali","sampradaya":"Shakta","significance":[],"country":"India","state":"Kerala","district":"Thrissur","town":"Puthenpeedika","latitude":10.44005,"longitude":76.12626,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Karuvannur River","river_distance_km":2.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:59.708182+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An ancient temple to Bhadrakali at Puthenpeedika, Kerala, described as a classic example of Kerala temple architecture. It takes part in the Arattupuzha Pooram, a gathering of deities from neighbouring shrines. Sub-shrines house Vigneswara, Veerabadran and Kandakarnan, plus a shrine for Rakshasas, and the goddess is believed to be sister of the Thiruvanikavu deity.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":43.9,"nearest_railway_station_name":"Thrissur Railway Station - West Entry railway station","nearest_railway_distance_km":12.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Thoniyakavu Bhadrakali Temple), summarised; location via OpenStreetMap","architecture_style":"Kerala","construction_century":null},{"id":"3e9a4b87-63a3-44f7-ab7d-431fe1a60aa7","name":"Kottarakkara Ganapathy Temple","deity":"Ganapathy (Ganesha)","sampradaya":"Ganapatya","significance":[],"country":"India","state":"Kerala","district":"Kollam","town":"Kottarakkara","latitude":9,"longitude":76.7833,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pulamon thodu River","river_distance_km":0.6,"best_season_notes":"Aug–Sep for Vinayaka Chaturthi; otherwise Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T18:27:49.795249+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Originally a Shiva temple (Kizhakkekara), where a subordinate Ganesha shrine grew to eclipse the main deity in popular devotion over time. Tradition holds a sculptor commissioned to carve a Vishnu idol was divinely guided to carve Ganesha instead, later consecrated by the legendary Kerala craftsman Perumthachan. The temple also holds a place in Kerala's performing arts history as the site traditionally credited with the first-ever Kathakali performance, in the 17th century.","etiquette_notes":null,"native_name":"കൊട്ടാരക്കര ഗണപതി ക്ഷേത്രം","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Thiruvananthapuram International Airport","nearest_airport_distance_km":59.5,"nearest_railway_station_name":"Kottarakara railway station","nearest_railway_distance_km":1.9,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":17},{"id":"3ea1aa78-bc6d-4289-ae30-53a50e128f85","name":"Jaladheeswara Temple","deity":"Shiva as Jaladheeswara with Balaparvati","sampradaya":"Shaiva","significance":[],"country":"India","state":"Andhra Pradesh","district":"Krishna","town":"Bollapadu","latitude":16.16962,"longitude":80.94436,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Krishna River","river_distance_km":9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:53.924452+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva temple at Ghantasala in Krishna district, Andhra Pradesh, believed by an ASI officer to predate the 2nd century CE. It is distinctive for placing Shiva and Parvati on a single peetam, which tradition says was set by Sage Agastya. The Skanda Purana is cited as equating a visit here with several major pilgrimages.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vijayawada Airport","nearest_airport_distance_km":42.6,"nearest_railway_station_name":"Repalle railway station","nearest_railway_distance_km":20.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Jaladheeswara Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"3effed24-b75a-430f-a7b9-f075ffc3fe4d","name":"Lakshana Devi Temple, Bharmour","deity":"Durga as Mahishasuramardini","sampradaya":"Shakta","significance":[],"country":"India","state":"Himachal Pradesh","district":"Chamba","town":"Bharmour","latitude":32.44231,"longitude":76.53742,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Budhil Nadi River","river_distance_km":1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A post-Gupta temple in Bharmour dated to the later 7th century, among the oldest surviving wooden temples in India. Although repairs have given it a hut-like look, its carved wooden doorway, interior and ceiling are preserved. A late Gupta inscription below the brass goddess image supports its age, and the carvings include Shaiva and Vaishnava themes.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kangra Airport, Gaggal","nearest_airport_distance_km":40.2,"nearest_railway_station_name":"Nagrota railway station","nearest_railway_distance_km":39.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Lakshana Devi Temple, Bharmour), summarised; location via OpenStreetMap","architecture_style":"Wooden, late Gupta style","construction_century":7},{"id":"3f16ea12-7cb0-4c7b-a5f0-9edbd9dfe0f0","name":"Kamakhya Temple","deity":"Kamakhya (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Assam","district":"Kamrup Metropolitan","town":"Guwahati","latitude":26.1665,"longitude":91.7036,"sandhya_friendly":"yes","sandhya_notes":"Atop Nilachal Hill overlooking the Brahmaputra; the riverfront ghats are a drive away.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Anna Seva Kendra near the shrine — free khichdi bhog daily; note that a separate non-vegetarian bhog is also part of temple tradition, so ask specifically for the vegetarian line","food_source_contact":null,"food_distance_km":0.1,"nearest_river_name":"Brahmaputra","river_distance_km":2,"best_season_notes":"Oct–Mar; the temple closes for three days during Ambubachi Mela (June) — check dates before visiting then.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Among the most important Shakti Peethas, where the yoni of Sati is said to have fallen. There is no image in the sanctum; a cleft in the rock, kept moist by a spring, is worshipped instead. The temple closes for three days during Ambubachi, when the goddess is held to undergo her annual courses.","etiquette_notes":null,"native_name":"কামাখ্যা দেৱালয়","morning_opens_at":"05:30:00","morning_closes_at":"13:00:00","evening_opens_at":"14:30:00","evening_closes_at":"17:30:00","timings_notes":"Closed for about three days during the Ambubachi Mela in June; may open earlier on Mondays and festival days.","accessibility_notes":null,"nearest_airport_name":"Lokpriya Gopinath Bordoloi International Airport","nearest_airport_distance_km":13.3,"nearest_railway_station_name":"Kamakhya Junction railway station","nearest_railway_distance_km":1.5,"emergency_contact_notes":null,"sthala_purana_source":"Devi Bhagavata Purana / Shakti Peetha tradition (Sati-limb legend)","architecture_style":"Nilachal style — a bulbous, beehive-shaped brick shikhara pioneered at this temple — rebuilt after the original stone structure was destroyed","construction_century":16},{"id":"3f45a62e-fb42-46c4-9fa9-dec773581875","name":"Sundernath","deity":"Shiva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Bihar","district":"Araria","town":"Balchanda","latitude":26.38102,"longitude":87.39348,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Parmān Nadi River","river_distance_km":6.3,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Sundarnath is a Shiva temple at Sundari Math, also called Sundarnath Dham, near the India-Nepal border in Araria district, Bihar. Hindus from southern Nepal and northern Bihar worship here, and it is described as a major historic Shiva temple of the Mithila region.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Purnea Airport","nearest_airport_distance_km":68.5,"nearest_railway_station_name":"Jogbani railway station","nearest_railway_distance_km":13.1,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Sundernath), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"3f4fc8d2-5e4e-4bb7-bad5-1acfc771b4da","name":"Kanthaswamy temple, Cheyyur","deity":"Murugan as Kanthaswamy","sampradaya":"Kaumara","significance":[],"country":"India","state":"Tamil Nadu","district":"Chengalpattu","town":"Cheyur","latitude":12.3525,"longitude":80.03944,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":null,"river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:59.708182+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"A Murugan temple at Cheyyur, Chengalpattu district, Tamil Nadu, built under the Cholas in the 10th century in the ancient Tamil style. Murugan is worshipped as Kanthaswamy with Valli and Deivasena, within a granite wall. Major festivals include Vaikasi Visagam, Kanthasasti, Thaipoosam and Panguni Uthiram.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Open 6 am to 12:30 pm and 4:30 to 8:00 pm on all days.","accessibility_notes":null,"nearest_airport_name":"Puducherry Airport","nearest_airport_distance_km":49.3,"nearest_railway_station_name":"Madurantakam railway station","nearest_railway_distance_km":23.2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Kanthaswamy temple, Cheyyur), summarised; location via OpenStreetMap","architecture_style":"Tamil","construction_century":10},{"id":"3f57662c-7ccf-408e-b5e8-8920c8f9f6fd","name":"Pandava Thoothar Perumal Temple, Kanchipuram","deity":"Pandava Tutar Perumal (Krishna) / Rukmini","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Tamil Nadu","district":"Kanchipuram","town":"Kanchipuram","latitude":12.8425,"longitude":79.69694,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vegavathy","river_distance_km":1.5,"best_season_notes":"Nov–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-09T13:54:39.898029+00:00","updated_at":"2026-11-04T12:15:48.914317+00:00","sthala_purana":"Also called Thirupadagam, one of the 108 Divya Desams and considered one of the three oldest temples in Kanchipuram. Krishna is worshipped here as Pandava Tutar Perumal, commemorating his role as envoy (thoothu) for the Pandavas before the Kurukshetra war.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":53.7,"nearest_railway_station_name":"Kanchipuram railway station","nearest_railway_distance_km":1.1,"emergency_contact_notes":null,"sthala_purana_source":"Nalayira Divya Prabandham; Mahabharata tradition","architecture_style":"Dravidian, among the oldest in Kanchipuram","construction_century":null},{"id":"3fdba30e-c837-4487-b003-ab074d60c3a0","name":"Bhooteshwarnath","deity":"Shiva (natural Shivalinga)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Chhattisgarh","district":"Gariaband","town":"Gariaband","latitude":20.60836,"longitude":82.04549,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Sondur River","river_distance_km":4.1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva temple near Marouda village, in the Gariaband forests, built around a naturally formed linga said to be the second largest in the world. Local belief holds that the linga keeps growing, and officials measure it yearly. Pilgrims bring water on Mahashivratri and on Mondays in Sawan.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Swami Vivekananda Airport","nearest_airport_distance_km":71.2,"nearest_railway_station_name":"Rajim railway station","nearest_railway_distance_km":44.2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Bhooteshwarnath), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"3fe979e8-ffda-4bf2-9de4-98121a93565c","name":"Varadharaja Perumal Temple, Puducherry","deity":"Varadharaja Perumal (Vishnu) with Perundevi Thayar (Lakshmi); the main idol is a five-foot standing granite figure","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Puducherry","district":"Puducherry","town":"Puducherry","latitude":11.9408,"longitude":79.83,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Chenjiyaru River","river_distance_km":6.9,"best_season_notes":"Ten-day Brahmotsavam in Chithrai (Apr–May), five-day Pavitrotsavam in Avani (Aug–Sep), and a 25-day Rama–Sita wedding festival in Chithrai.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-25T13:54:12.118115+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Tradition attributes the temple to the Cholas around the 11th century, with later Pandya expansion, but that attribution is repeated mainly by tourism sources and is not a dated fact. The temple was reportedly damaged and rebuilt during 17th–18th century conflicts, and statues of Rama, Sita, Hanuman and Krishna were unearthed and reinstalled in 1902. Sources differ slightly on which subsidiary idols are installed.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Per Pondicherry Tourism (a commercial tourism site, not the temple's own schedule): roughly 6am–12pm and 4–9pm; free entry.","accessibility_notes":null,"nearest_airport_name":"Puducherry Airport","nearest_airport_distance_km":3.7,"nearest_railway_station_name":"Puducherry Railway Station","nearest_railway_distance_km":2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Varadharaja Perumal Temple, Puducherry); Chola attribution is traditional and unverified","architecture_style":"Dravidian; five-tiered rajagopuram of about 34 m with a granite enclosure wall","construction_century":null},{"id":"40282610-5b76-4f8d-8e4f-7490e38f04ee","name":"Chintpurni Temple","deity":"Chinnamastika Devi","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Himachal Pradesh","district":"Una","town":"Chintpurni","latitude":31.8215,"longitude":76.1298,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Beas River","river_distance_km":9.1,"best_season_notes":"Mar–Jun and Sept–Nov; both Navratri seasons are very crowded.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of the Shakti Peethas, traditionally held to mark where Sati's feet fell. The presiding form, Chhinnamasta, is depicted holding her own severed head — one of the more esoteric and tantric forms of the Devi — though the temple itself is a major, well-visited pilgrimage stop on the Himachal Shakti Peetha circuit alongside Naina Devi and Jwalamukhi.","etiquette_notes":null,"native_name":"छिन्नपूर्णी मन्दिर","morning_opens_at":"05:00:00","morning_closes_at":"22:00:00","evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Open continuously through the day; winter hours run 4am–10pm and summer roughly 5:30am–9:30pm. Closed during a solar/lunar eclipse (grahan).","accessibility_notes":null,"nearest_airport_name":"Kangra Airport, Gaggal","nearest_airport_distance_km":40.2,"nearest_railway_station_name":"Daulatpur Chowk railway station","nearest_railway_distance_km":12.8,"emergency_contact_notes":null,"sthala_purana_so