 temple","deity":"Shiva as Mahadev","sampradaya":"Shaiva","significance":[],"country":"India","state":"Uttar Pradesh","district":"Varanasi","town":"Varanasi","latitude":25.3119,"longitude":83.01603,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Ganges River","river_distance_km":0.1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:44.755986+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Known as the leaning temple of Varanasi, this Mahadev shrine stands at Manikarnika Ghat and is among the most photographed temples in the city. It tilts about nine degrees toward the north-west, and its sanctum is under water for much of the year except for a few summer months.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Lal Bahadur Shastri International Airport","nearest_airport_distance_km":21.8,"nearest_railway_station_name":"Kashi railway station","nearest_railway_distance_km":2.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Ratneshwar Mahadev temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"438d7e4e-686e-411f-b1f4-d7baab5a4029","name":"Thrikodithanam Mahavishnu Temple","deity":"Atputha Narayana (Vishnu)","sampradaya":"Vaishnava","significance":["Malai Nadu Divya Desam"],"country":"India","state":"Kerala","district":"Kottayam","town":"Thrikodithanam","latitude":9.4381,"longitude":76.5619,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Manimala River","river_distance_km":6.7,"best_season_notes":"Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-06T08:12:33.253723+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of the Malai Nadu Divya Desams and the last of five Pandava-built shrines of the Chengannur area, tradition crediting this one to Sahadeva — who, unable to find a Vishnu murti as his four brothers had, is said to have been on the verge of ending his life on a pyre when a four-armed image of Vishnu miraculously appeared from the flames, worshipped since as Atputha (\"wondrous\") Narayana. The temple is mentioned in the 16th-century Unniyachi Charitham and records a 965 CE donation by the Venad crown prince.","etiquette_notes":null,"native_name":"തൃക്കൊടിത്താനം മഹാക്ഷേത്രം","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":81.5,"nearest_railway_station_name":"Changanasseri railway station","nearest_railway_distance_km":1.9,"emergency_contact_notes":null,"sthala_purana_source":"Mahabharata tradition; historical inscriptions","architecture_style":null,"construction_century":null},{"id":"43935b99-6845-4d43-ad9b-1e4e0027b035","name":"Gondeshwar Temple, Sinnar","deity":"Shiva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Maharashtra","district":"Nashik","town":"Sinnar","latitude":19.8514,"longitude":74.0019,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dev River","river_distance_km":2.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verif